package io.github.jesterportfolio.hearth.economy;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class EconomyMerchantsTest {
    private Properties settings(){try(var r=new java.io.InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/economy-demo.properties")),java.nio.charset.StandardCharsets.UTF_8)){var p=new Properties();p.load(r);return p;}catch(Exception e){throw new AssertionError(e);}}
    private final Properties p=settings();private final EconomyContent content=EconomyContent.parse(p);
    private EconomyStore.Offer offer(String region,String good){return new EconomyStore.Offer(new EconomyContent.Key(region,good),new EconomyEngine.Market(100,100,0),10000);}
    @Test void twoMerchantsHaveIndependentRegionsGoodsAndPoints(){var catalog=EconomyMerchants.parse(p,content);assertEquals(2,catalog.all().size());var city=catalog.get("capital_trader");var mine=catalog.get("mine_trader");assertEquals("capital",city.shop().region());assertEquals("mine",mine.shop().region());assertEquals(List.of("iron_ore"),mine.shop().goods());assertNotEquals(city.point(),mine.point());assertThrows(UnsupportedOperationException.class,()->catalog.all().clear());}
    @Test void legacySingleMerchantConfigurationStillWorks(){var legacy=settings();legacy.remove("merchants");var catalog=EconomyMerchants.parse(legacy,content);assertEquals(1,catalog.all().size());assertEquals("legacy_merchant",catalog.first().id());assertEquals(7.5,catalog.first().point().x());assertEquals("capital",catalog.first().shop().region());}
    @Test void invalidMerchantReferencesAndDuplicateIdsFail(){for(var pair:Map.of("merchants","capital_trader,capital_trader","merchant.mine_trader.region","missing","merchant.mine_trader.goods","missing","merchant.mine_trader.name","").entrySet()){var bad=settings();bad.setProperty(pair.getKey(),pair.getValue());assertThrows(IllegalArgumentException.class,()->EconomyMerchants.parse(bad,content));}var missing=settings();missing.remove("merchant.mine_trader.x");assertThrows(RuntimeException.class,()->EconomyMerchants.parse(missing,content));}
    @Test void nonFiniteAndExtremePositionsFail(){for(double value:new double[]{Double.NaN,Double.POSITIVE_INFINITY,30000000})assertThrows(IllegalArgumentException.class,()->new EconomyMerchants.Point(value,64,0));assertThrows(IllegalArgumentException.class,()->new EconomyMerchants.Point(0,-5000,0));}
    @Test void wrongRegionAndUnsupportedGoodsCannotBeSelected(){var mine=EconomyMerchants.parse(p,content).get("mine_trader");assertDoesNotThrow(()->mine.require(offer("mine","iron_ore")));assertThrows(IllegalArgumentException.class,()->mine.require(offer("capital","iron_ore")));assertThrows(IllegalArgumentException.class,()->mine.require(offer("mine","iron_ingot")));}
    @Test void mixedDuplicateAndMissingOffersFailBeforeRendering(){var city=EconomyMerchants.parse(p,content).get("capital_trader").shop();assertThrows(IllegalArgumentException.class,()->city.index(List.of(offer("capital","iron_ingot"))));assertThrows(IllegalArgumentException.class,()->city.index(List.of(offer("capital","iron_ingot"),offer("mine","iron_ore"))));assertThrows(IllegalArgumentException.class,()->city.index(List.of(offer("capital","iron_ingot"),offer("capital","iron_ingot"))));assertEquals(2,city.index(List.of(offer("capital","iron_ingot"),offer("capital","iron_ore"))).size());}
    @Test void lateVisitCannotCrossMerchantEntityOrGeneration(){UUID city=UUID.randomUUID(),mine=UUID.randomUUID();var old=new EconomyMerchants.Visit("capital_trader",city,1);var current=new EconomyMerchants.Visit("mine_trader",mine,1);assertTrue(old.current(old,city,1));assertFalse(old.current(current,city,1));assertFalse(old.current(old,UUID.randomUUID(),1));assertFalse(old.current(old,city,2));assertFalse(old.current(new EconomyMerchants.Visit("capital_trader",city,1),city,1));assertFalse(old.current(null,null,1));}
    @Test void distinctRegionalQuotesUseTheirOwnMarketState(){var catalog=EconomyMerchants.parse(p,content);var mine=catalog.get("mine_trader");var city=catalog.get("capital_trader");var cheap=new EconomyStore.Offer(new EconomyContent.Key("mine","iron_ore"),new EconomyEngine.Market(200,100,0),1000);var expensive=new EconomyStore.Offer(new EconomyContent.Key("capital","iron_ore"),new EconomyEngine.Market(50,150,0),1000);assertTrue(mine.shop().prices(content,cheap).getFirst().total()<city.shop().prices(content,expensive).getFirst().total());assertThrows(IllegalArgumentException.class,()->mine.shop().prices(content,expensive));}
    @Test void chunkLookupOnlyReturnsConfiguredImmutableMerchants(){var catalog=EconomyMerchants.parse(p,content);assertEquals(2,catalog.inChunk(0,0).size());assertTrue(catalog.inChunk(1,0).isEmpty());assertThrows(UnsupportedOperationException.class,()->catalog.inChunk(0,0).clear());var negative=settings();negative.setProperty("merchant.mine_trader.x","-0.5");assertEquals("mine_trader",EconomyMerchants.parse(negative,content).inChunk(-1,0).getFirst().id());}
}
